#!/usr/bin/env bash
set -Eeuo pipefail
ROOT=$(cd "$(dirname "$0")/../../.."&&pwd);BUILD=${1:?build directory};PKG=$BUILD/PromoteToKing_v2.12.0_INCREMENTAL;I=$PKG/install-promote-to-king-v2.12.0.sh
BASE=(2.11.0:2ca1fc191aeef444b4886b53e25a54a83820c25c 2.11.1:b8bf26c7c41ca1914323717766bca995139291aa 2.11.2:4ececcc230ca07099b346cb47396ad00bedd5c21 2.11.3:dcd71c8e76c07defacf6270aff4224b10484968b 2.11.4:6706e619d310e2c74fe2734cfcef8dd2f83d70d1 2.11.5:c534b2dbb0346eac0fa6de869621d6b7d785ead8);W=$(mktemp -d);trap 'rm -rf -- "$W"' EXIT;mkdir "$W/bin";printf '#!/bin/bash\n[[ $1 == -l ]]&&cat "$P2K_QUALIFICATION_CRONTAB"\n'>"$W/bin/crontab";chmod +x "$W/bin/crontab";echo '17 3 * * * /srv/p2k/cron.sh --unchanged'>"$W/cron";CH=$(sha256sum "$W/cron")
fixture(){ mkdir -p "$1/config/local" "$1/data/q" "$1/server/team-points/storage" "$1/logs";echo secret>"$1/config/local/secret.env";echo data>"$1/data/q/state";echo db>"$1/server/team-points/storage/state";echo log>"$1/logs/log";};pres(){ (cd "$1"&&sha256sum config/local/secret.env data/q/state server/team-points/storage/state logs/log);};managed(){ (cd "$1"&&while IFS= read -r f;do sha256sum "$f";done<"$PKG/FILES.list");}
REF=
for e in "${BASE[@]}";do l=${e%%:*};r=${e#*:};t=$W/$l;mkdir "$t";git -C "$ROOT" archive "$r"|tar -x -C "$t";fixture "$t";pres "$t">"$W/$l.before";PATH="$W/bin:$PATH" P2K_QUALIFICATION_CRONTAB="$W/cron" "$I" "$t";"$I" "$t" verify;pres "$t">"$W/$l.after";diff -u "$W/$l.before" "$W/$l.after";[[ $CH == "$(sha256sum "$W/cron")" ]];managed "$t">"$W/$l.managed";if [[ -z $REF ]];then REF=$W/$l.managed;else diff -u "$REF" "$W/$l.managed";fi;PATH="$W/bin:$PATH" P2K_QUALIFICATION_CRONTAB="$W/cron" "$I" "$t";managed "$t">"$W/$l.re";diff -u "$W/$l.managed" "$W/$l.re";echo "qualified $l";done
t=$W/rollback;mkdir "$t";git -C "$ROOT" archive c534b2dbb0346eac0fa6de869621d6b7d785ead8|tar -x -C "$t";fixture "$t";(cd "$t"&&find . -type f -print0|sort -z|xargs -0 sha256sum)>"$W/r.before";if PATH="$W/bin:$PATH" P2K_QUALIFICATION_CRONTAB="$W/cron" P2K_FORCE_INSTALL_FAILURE_AFTER=5 "$I" "$t";then exit 1;fi;(cd "$t"&&find . -type f -print0|sort -z|xargs -0 sha256sum)>"$W/r.after";diff -u "$W/r.before" "$W/r.after";[[ $CH == "$(sha256sum "$W/cron")" ]];echo 'universal installer matrix, convergence, idempotency and rollback passed'
